/**
 * SPARQL-level edge cases of the {@code agg:} extension aggregates that need query context (grouping, HAVING, term
 * equality under DISTINCT, window functions, sub-select ordering, magic properties), one method per case of the GH-6193
 * edge-case plan.
 */
public class ExtensionAggregateEdgeCaseSparqlTest {

	private static final String PREFIXES = "PREFIX agg: <http://rdf4j.org/aggregate#>\n"
			+ "PREFIX arrf: <http://rdf4j.org/function/array#>\n"
			+ "PREFIX winf: <http://rdf4j.org/function/window#>\n"
			+ "PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n"
			+ "PREFIX ex: <http://example.org/>\n";

	private static final String ALL_UNARY = " (agg:median(?x) AS ?median) (agg:mode(?x) AS ?mode)"
			+ " (agg:countIf(?x) AS ?countIf) (agg:boolAnd(?x) AS ?boolAnd) (agg:boolOr(?x) AS ?boolOr)"
			+ " (agg:first(?x) AS ?first) (agg:last(?x) AS ?last)"
			+ " (agg:approxCountDistinct(?x) AS ?approxCountDistinct) (agg:histogram(?x) AS ?histogram)"
			+ " (agg:arrayAgg(?x) AS ?arrayAgg)";

	private static final String ALL_NARY = " (agg:percentileCont(?x, 0.5) AS ?percentileCont)"
			+ " (agg:percentileDisc(?x, 0.5) AS ?percentileDisc) (agg:approxQuantile(?x, 0.5) AS ?approxQuantile)"
			+ " (agg:corr(?x, ?x) AS ?corr) (agg:covarPop(?x, ?x) AS ?covarPop) (agg:covarSamp(?x, ?x) AS ?covarSamp)"
			+ " (agg:argMin(?x, ?x) AS ?argMin) (agg:argMax(?x, ?x) AS ?argMax)";

	private static final List<String> UNBOUND_ON_EMPTY = List.of("median", "mode", "boolAnd", "boolOr", "first",
			"last", "percentileCont", "percentileDisc", "approxQuantile", "corr", "covarPop", "covarSamp", "argMin",
			"argMax");

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static SailRepository repository;

	@BeforeAll
	static void setUp() throws Exception {
		repository = new SailRepository(new MemoryStore());
		String data = "@prefix ex: <http://example.org/> .\n"
				+ "ex:e1 ex:dept ex:sales ; ex:salary 10 ; ex:age 30 ; ex:active true .\n"
				+ "ex:e2 ex:dept ex:sales ; ex:salary 30 ; ex:age 40 ; ex:active true .\n"
				+ "ex:e3 ex:dept ex:sales ; ex:salary 20 ; ex:age 35 ; ex:active false .\n"
				+ "ex:e4 ex:dept ex:eng ; ex:salary 50 ; ex:age 50 ; ex:active true .\n"
				+ "ex:e5 ex:dept ex:eng ; ex:salary 70 ; ex:age 60 ; ex:active true .\n"
				+ "ex:e6 ex:dept ex:eng ; ex:salary 70 .\n"
				+ "_:b1 ex:kind ex:bnode ; ex:tag \"one\" .\n"
				+ "_:b2 ex:kind ex:bnode ; ex:tag \"two\" .\n";
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader(data), "", RDFFormat.TURTLE);
		}
	}

	@AfterAll
	static void tearDown() {
		repository.shutDown();
	}

	private static List<BindingSet> query(String query) {
		try (RepositoryConnection conn = repository.getConnection();
				TupleQueryResult result = conn.prepareTupleQuery(PREFIXES + query).evaluate()) {
			return new ArrayList<>(QueryResults.asList(result));
		}
	}

	private static String str(BindingSet bs, String var) {
		assertThat(bs.hasBinding(var)).as(var + " bound in " + bs).isTrue();
		return bs.getValue(var).stringValue();
	}

	private static Literal lit(BindingSet bs, String var) {
		assertThat(bs.hasBinding(var)).as(var + " bound in " + bs).isTrue();
		return (Literal) bs.getValue(var);
	}

	private static List<String> column(List<BindingSet> rows, String var) {
		List<String> values = new ArrayList<>(rows.size());
		for (BindingSet row : rows) {
			values.add(row.hasBinding(var) ? row.getValue(var).stringValue() : null);
		}
		return values;
	}

	private static void assertEmptyGroupShape(BindingSet row) {
		for (String name : UNBOUND_ON_EMPTY) {
			assertThat(row.hasBinding(name)).as(name).isFalse();
		}
		assertThat(lit(row, "countIf")).isEqualTo(VF.createLiteral("0", XSD.INTEGER));
		assertThat(lit(row, "approxCountDistinct")).isEqualTo(VF.createLiteral("0", XSD.INTEGER));
		assertThat(lit(row, "histogram")).isEqualTo(VF.createLiteral("[]", CoreDatatype.RDF.JSON));
		assertThat(lit(row, "arrayAgg")).isEqualTo(VF.createLiteral("[]", CoreDatatype.RDF.JSON));
	}

	// ------------------------------------------------------------------ family-wide

	@Test
	void emptyGroupLeavesMostAggregatesUnbound() {
		List<BindingSet> rows = query("SELECT" + ALL_UNARY + ALL_NARY + " WHERE { ?s ex:nothing ?x }");
		assertThat(rows).hasSize(1);
		assertEmptyGroupShape(rows.get(0));
		// with GROUP BY an empty input produces no groups at all
		assertThat(query("SELECT ?g (agg:median(?x) AS ?m) WHERE { ?s ex:nothing ?x ; ex:g ?g } GROUP BY ?g"))
				.isEmpty();
	}

	@Test
	void groupWithOnlyUnboundValuesBehavesLikeEmptyGroup() {
		// pins current behaviour: unbound values are skipped, so a group of unbound values is an empty group
		List<BindingSet> rows = query("SELECT" + ALL_UNARY + ALL_NARY
				+ " WHERE { ?e ex:dept ?d OPTIONAL { ?e ex:nothing ?x } }");
		assertThat(rows).hasSize(1);
		assertEmptyGroupShape(rows.get(0));
		List<BindingSet> grouped = query("SELECT ?d (COUNT(*) AS ?n)" + ALL_UNARY + ALL_NARY
				+ " WHERE { ?e ex:dept ?d OPTIONAL { ?e ex:nothing ?x } } GROUP BY ?d ORDER BY ?d");
		assertThat(grouped).hasSize(2);
		assertThat(column(grouped, "n")).containsExactly("3", "3");
		for (BindingSet row : grouped) {
			assertEmptyGroupShape(row);
		}
	}

	@Test
	void singleErroringValuePoisonsOnlyTypedAggregates() {
		// a string among numbers is an error for the numeric aggregates, which become unbound; term-agnostic
		// aggregates and the standard COUNT in the same group are unaffected
		List<BindingSet> rows = query("SELECT (COUNT(?x) AS ?n)" + ALL_UNARY + ALL_NARY
				+ " WHERE { VALUES ?x { 1 2 \"three\" 4 } }");
		assertThat(rows).hasSize(1);
		BindingSet row = rows.get(0);
		assertThat(str(row, "n")).isEqualTo("4");
		for (String numeric : List.of("median", "percentileCont", "percentileDisc", "approxQuantile", "corr",
				"covarPop", "covarSamp")) {
			assertThat(row.hasBinding(numeric)).as(numeric).isFalse();
		}
		assertThat(str(row, "mode")).isEqualTo("1");
		assertThat(str(row, "first")).isEqualTo("1");
		assertThat(str(row, "last")).isEqualTo("4");
		assertThat(str(row, "countIf")).isEqualTo("4");
		assertThat(str(row, "approxCountDistinct")).isEqualTo("4");
		assertThat(str(row, "arrayAgg")).isEqualTo("[1,2,\"three\",4]");
		assertThat(str(row, "histogram")).contains("\"value\":\"three\"");
		assertThat(str(row, "argMin")).isEqualTo("1");
		assertThat(str(row, "argMax")).isEqualTo("three");
		// one IRI among booleans poisons boolAnd/boolOr but not countIf
		List<BindingSet> bools = query("SELECT (agg:boolAnd(?b) AS ?and) (agg:boolOr(?b) AS ?or)"
				+ " (agg:countIf(?b) AS ?c) WHERE { VALUES ?b { true <urn:x> true } }");
		assertThat(bools.get(0).hasBinding("and")).isFalse();
		assertThat(bools.get(0).hasBinding("or")).isFalse();
		assertThat(str(bools.get(0), "c")).isEqualTo("2");
	}

	@Test
	void erroringArgumentExpressionRowsAreSkipped() {
		// pins current behaviour: a solution whose argument *expression* errors contributes nothing (as for COUNT),
		// unlike a bound value of the wrong type which poisons the aggregate
		List<BindingSet> rows = query("SELECT (agg:median(xsd:integer(?x)) AS ?m) (agg:countIf(?x > 1) AS ?c)"
				+ " (agg:arrayAgg(xsd:integer(?x)) AS ?arr) (agg:percentileCont(xsd:integer(?x), 0.5) AS ?p)"
				+ " WHERE { VALUES ?x { \"1\" \"x\" \"3\" } }");
		assertThat(str(rows.get(0), "m")).isEqualTo("2");
		assertThat(str(rows.get(0), "p")).isEqualTo("2");
		assertThat(str(rows.get(0), "c")).isEqualTo("0");
		assertThat(str(rows.get(0), "arr")).isEqualTo("[1,3]");
	}

	@Test
	void distinctComparesRdfTermsNotNumericValues() {
		// pins current behaviour: DISTINCT removes duplicate RDF terms, so 1 and "1"^^xsd:integer collapse while
		// 1.0 (decimal) and 01 (non-canonical lexical form) stay separate
		List<BindingSet> rows = query("SELECT (COUNT(DISTINCT ?x) AS ?n) (agg:arrayAgg(DISTINCT ?x) AS ?arr)"
				+ " (agg:approxCountDistinct(?x) AS ?approx) (agg:median(DISTINCT ?x) AS ?m)"
				+ " (agg:countIf(DISTINCT ?x) AS ?c) WHERE { VALUES ?x { 1 1.0 \"1\"^^xsd:integer 01 1 } }");
		BindingSet row = rows.get(0);
		assertThat(str(row, "n")).isEqualTo("3");
		assertThat(str(row, "approx")).isEqualTo("3");
		assertThat(str(row, "arr"))
				.isEqualTo("[1,1.0,{\"@value\":\"01\",\"@type\":\"http://www.w3.org/2001/XMLSchema#integer\"}]");
		assertThat(lit(row, "m").decimalValue()).isEqualByComparingTo(BigDecimal.ONE);
		assertThat(str(row, "c")).isEqualTo("3");
	}

	@Test
	void mixedNumericDatatypesPromoteAndStringsPoison() {
		List<BindingSet> rows = query("SELECT (agg:median(?x) AS ?m) (agg:percentileCont(?x, 0.5) AS ?p)"
				+ " WHERE { VALUES ?x { 1 2.0 \"3\"^^xsd:byte 4 } }");
		assertThat(lit(rows.get(0), "m").getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DECIMAL);
		assertThat(str(rows.get(0), "m")).isEqualTo("2.5");
		assertThat(str(rows.get(0), "p")).isEqualTo("2.5");
		rows = query("SELECT (agg:median(?x) AS ?m) WHERE { VALUES ?x { 1 2.0 3e0 4 } }");
		assertThat(lit(rows.get(0), "m").getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DOUBLE);
		assertThat(lit(rows.get(0), "m").doubleValue()).isEqualTo(2.5);
		rows = query("SELECT (agg:median(?x) AS ?m) (agg:covarPop(?x, ?x) AS ?cv)"
				+ " WHERE { VALUES ?x { 1 \"2\" 3 } }");
		assertThat(rows.get(0).hasBinding("m")).isFalse();
		assertThat(rows.get(0).hasBinding("cv")).isFalse();
	}

	@Test
	void extensionAggregatesInHaving() {
		List<BindingSet> rows = query("SELECT ?dept (agg:median(?salary) AS ?m) WHERE {"
				+ " ?e ex:dept ?dept ; ex:salary ?salary } GROUP BY ?dept HAVING (agg:median(?salary) > 25)");
		assertThat(rows).hasSize(1);
		assertThat(str(rows.get(0), "dept")).endsWith("eng");
		assertThat(str(rows.get(0), "m")).isEqualTo("70");
		// the compared form; the *bare* form HAVING (agg:boolAnd(?active)) is covered by HavingRootAggregateSparqlTest
		rows = query("SELECT ?dept WHERE { ?e ex:dept ?dept OPTIONAL { ?e ex:active ?active } }"
				+ " GROUP BY ?dept HAVING (agg:boolAnd(?active) = true)");
		assertThat(column(rows, "dept")).containsExactly("http://example.org/eng");
		rows = query("SELECT ?dept WHERE { ?e ex:dept ?dept OPTIONAL { ?e ex:active ?active } }"
				+ " GROUP BY ?dept HAVING (!agg:boolAnd(?active) && agg:boolOr(?active))");
		assertThat(column(rows, "dept")).containsExactly("http://example.org/sales");
		rows = query("SELECT ?dept WHERE { ?e ex:dept ?dept ; ex:salary ?salary }"
				+ " GROUP BY ?dept HAVING (agg:countIf(?salary >= 30) = 1)");
		assertThat(column(rows, "dept")).containsExactly("http://example.org/sales");
		rows = query("SELECT ?dept WHERE { ?e ex:dept ?dept ; ex:salary ?salary }"
				+ " GROUP BY ?dept HAVING (agg:percentileDisc(?salary, 0.5) = 70)");
		assertThat(column(rows, "dept")).containsExactly("http://example.org/eng");
	}

	@Test
	void extensionAggregatesTogetherWithStandardCount() {
		List<BindingSet> rows = query("SELECT ?dept (COUNT(*) AS ?n) (COUNT(?age) AS ?ages) (SUM(?salary) AS ?sum)"
				+ " (agg:median(?salary) AS ?median) (agg:mode(?salary) AS ?mode) (agg:countIf(?active) AS ?actives)"
				+ " (agg:argMax(?e, ?salary) AS ?top) (agg:corr(?salary, ?age) AS ?corr)"
				+ " WHERE { ?e ex:dept ?dept ; ex:salary ?salary OPTIONAL { ?e ex:age ?age } OPTIONAL { ?e ex:active"
				+ " ?active } } GROUP BY ?dept ORDER BY ?dept");
		assertThat(rows).hasSize(2);
		BindingSet eng = rows.get(0);
		assertThat(str(eng, "n")).isEqualTo("3");
		assertThat(str(eng, "ages")).isEqualTo("2");
		assertThat(str(eng, "sum")).isEqualTo("190");
		assertThat(str(eng, "median")).isEqualTo("70");
		assertThat(str(eng, "mode")).isEqualTo("70");
		assertThat(str(eng, "actives")).isEqualTo("2");
		assertThat(str(eng, "top")).matches("http://example.org/e[56]");
		assertThat(lit(eng, "corr").doubleValue()).isCloseTo(1.0, within(1e-12));
		BindingSet sales = rows.get(1);
		assertThat(str(sales, "n")).isEqualTo("3");
		assertThat(str(sales, "median")).isEqualTo("20");
		assertThat(str(sales, "actives")).isEqualTo("2");
		assertThat(str(sales, "top")).endsWith("e2");
	}

	@Test
	void withoutGroupByTheWholeResultSetIsOneGroup() {
		List<BindingSet> rows = query("SELECT (agg:median(?salary) AS ?median) (agg:first(?dept) AS ?someDept)"
				+ " (agg:approxCountDistinct(?dept) AS ?depts) (agg:percentileDisc(?salary, 1) AS ?max)"
				+ " (agg:argMin(?e, ?salary) AS ?lowest) (agg:arrayAgg(DISTINCT ?dept) AS ?deptArray)"
				+ " WHERE { ?e ex:dept ?dept ; ex:salary ?salary }");
		assertThat(rows).hasSize(1);
		BindingSet row = rows.get(0);
		assertThat(str(row, "median")).isEqualTo("40");
		assertThat(str(row, "someDept")).startsWith("http://example.org/");
		assertThat(str(row, "depts")).isEqualTo("2");
		assertThat(str(row, "max")).isEqualTo("70");
		assertThat(str(row, "lowest")).endsWith("e1");
		assertThat(str(row, "deptArray")).matches("\\[\\{\"@id\":\"http://example.org/\\w+\"\\},"
				+ "\\{\"@id\":\"http://example.org/\\w+\"\\}\\]");
	}

	@Test
	void largeGroupCompletesQuickly() {
		long start = System.nanoTime();
		List<BindingSet> rows = query("SELECT (agg:median(?n) AS ?median) (agg:countIf(?n > 50000) AS ?upper)"
				+ " (agg:approxCountDistinct(?n) AS ?distinct) (agg:approxQuantile(?n, 0.5) AS ?aq)"
				+ " (agg:percentileDisc(?n, 0.25) AS ?q1) (agg:percentileCont(?n, 0.75) AS ?q3)"
				+ " (arrf:arrayLength(agg:arrayAgg(?n)) AS ?len) (agg:argMax(?n, ?n) AS ?max)"
				+ " (agg:corr(?n, ?n) AS ?corr) (agg:last(?n) AS ?last)"
				+ " WHERE { (1 100000) arrf:generateSeries ?n }");
		long elapsedMillis = (System.nanoTime() - start) / 1_000_000;
		assertThat(rows).hasSize(1);
		BindingSet row = rows.get(0);
		assertThat(str(row, "median")).isEqualTo("50000.5");
		assertThat(str(row, "upper")).isEqualTo("50000");
		assertThat(lit(row, "distinct").longValue()).isBetween(98_000L, 102_000L);
		assertThat(lit(row, "aq").doubleValue()).isBetween(47_000.0, 53_000.0);
		assertThat(str(row, "q1")).isEqualTo("25000");
		assertThat(str(row, "q3")).isEqualTo("75000.25");
		assertThat(str(row, "len")).isEqualTo("100000");
		assertThat(str(row, "max")).isEqualTo("100000");
		assertThat(lit(row, "corr").doubleValue()).isCloseTo(1.0, within(1e-9));
		assertThat(str(row, "last")).isEqualTo("100000");
		assertThat(elapsedMillis).as("100 000 rows aggregated in %d ms", elapsedMillis).isLessThan(30_000);
	}

	@Test
	void aggregateNestedInsideWindowFunctionIsAllowed() {
		List<BindingSet> rows = query("SELECT ?dept (agg:median(?salary) AS ?median)"
				+ " (winf:rank(winf:orderBy(winf:desc(agg:median(?salary)))) AS ?rank)"
				+ " (winf:sum(agg:countIf(?active)) AS ?allActives)"
				+ " (winf:firstValue(agg:argMax(?e, ?salary), winf:orderBy(agg:median(?salary))) AS ?lowestTop)"
				+ " WHERE { ?e ex:dept ?dept ; ex:salary ?salary OPTIONAL { ?e ex:active ?active } }"
				+ " GROUP BY ?dept ORDER BY ?rank");
		assertThat(column(rows, "median")).containsExactly("70", "20");
		assertThat(column(rows, "rank")).containsExactly("1", "2");
		assertThat(column(rows, "allActives")).containsExactly("4", "4");
		assertThat(column(rows, "lowestTop")).containsExactly("http://example.org/e2", "http://example.org/e2");
	}

	@Test
	void windowFunctionInsideAggregateIsRejectedAtParseTime() {
		for (String projection : List.of("(agg:median(winf:rowNumber()) AS ?r)",
				"(agg:first(winf:rank(winf:orderBy(?salary))) AS ?r)",
				"(agg:percentileCont(?salary, winf:rowNumber()) AS ?r)",
				"(agg:countIf(winf:rowNumber() > 1) AS ?r)",
				"(agg:argMax(?e, winf:sum(?salary)) AS ?r)",
				"(agg:arrayAgg(winf:lag(?salary, 1, 0, winf:orderBy(?salary))) AS ?r)")) {
			assertThatThrownBy(() -> query("SELECT " + projection + " WHERE { ?e ex:salary ?salary }"))
					.as(projection)
					.isInstanceOf(MalformedQueryException.class)
					.hasMessageContaining("cannot be used inside an aggregate");
		}
	}

	// ------------------------------------------------------------------ first / last

	@Test
	void firstAndLastHonourSubSelectOrder() {
		// pins current behaviour: grouping preserves the order of the (ordered) sub-select, so first/last are the
		// minimum/maximum when the sub-select sorts ascending and swap when it sorts descending
		List<BindingSet> rows = query("SELECT ?dept (agg:first(?salary) AS ?first) (agg:last(?salary) AS ?last)"
				+ " WHERE { { SELECT ?dept ?salary WHERE { ?e ex:dept ?dept ; ex:salary ?salary }"
				+ " ORDER BY ?salary ?e } } GROUP BY ?dept ORDER BY ?dept");
		assertThat(column(rows, "first")).containsExactly("50", "10");
		assertThat(column(rows, "last")).containsExactly("70", "30");
		rows = query("SELECT ?dept (agg:first(?salary) AS ?first) (agg:last(?salary) AS ?last)"
				+ " WHERE { { SELECT ?dept ?salary WHERE { ?e ex:dept ?dept ; ex:salary ?salary }"
				+ " ORDER BY DESC(?salary) ?e } } GROUP BY ?dept ORDER BY ?dept");
		assertThat(column(rows, "first")).containsExactly("70", "30");
		assertThat(column(rows, "last")).containsExactly("50", "10");
	}

	@Test
	void firstSkipsLeadingUnboundValues() {
		// pins current behaviour: an unbound first value is skipped, first() returns the first *bound* value
		// a second variable keeps every solution non-empty (RDF4J's COUNT(*) does not count empty solutions)
		List<BindingSet> rows = query("SELECT (agg:first(?x) AS ?f) (agg:last(?x) AS ?l) (COUNT(*) AS ?n)"
				+ " WHERE { VALUES (?i ?x) { (1 UNDEF) (2 5) (3 6) (4 UNDEF) } }");
		assertThat(str(rows.get(0), "f")).isEqualTo("5");
		assertThat(str(rows.get(0), "l")).isEqualTo("6");
		assertThat(str(rows.get(0), "n")).isEqualTo("4");
		rows = query("SELECT (agg:first(?x) AS ?f) WHERE { VALUES ?x { UNDEF } }");
		assertThat(rows.get(0).hasBinding("f")).isFalse();
	}

	@Test
	void firstAndLastWithValuesOfDifferentTypes() {
		List<BindingSet> rows = query("SELECT (agg:first(?x) AS ?f) (agg:last(?x) AS ?l)"
				+ " WHERE { VALUES ?x { <urn:a> 1 \"s\"@en 2.5 } }");
		assertThat(str(rows.get(0), "f")).isEqualTo("urn:a");
		assertThat(str(rows.get(0), "l")).isEqualTo("2.5");
	}

	// ------------------------------------------------------------------ percentiles

	@Test
	void fractionVaryingWithinAGroupIsAnError() {
		List<BindingSet> rows = query("SELECT (COUNT(*) AS ?n) (agg:percentileCont(?x, ?p) AS ?pc)"
				+ " (agg:percentileDisc(?x, ?p) AS ?pd) (agg:approxQuantile(?x, ?p) AS ?aq)"
				+ " WHERE { VALUES (?x ?p) { (1 0.1) (2 0.9) (3 0.1) } }");
		assertThat(str(rows.get(0), "n")).isEqualTo("3");
		assertThat(rows.get(0).hasBinding("pc")).isFalse();
		assertThat(rows.get(0).hasBinding("pd")).isFalse();
		assertThat(rows.get(0).hasBinding("aq")).isFalse();
	}

	@Test
	void fractionConstantWithinGroupsMayDifferBetweenGroups() {
		List<BindingSet> rows = query("SELECT ?g (agg:percentileCont(?x, ?p) AS ?pc)"
				+ " (agg:percentileDisc(?x, ?p) AS ?pd) (agg:approxQuantile(?x, ?p) AS ?aq)"
				+ " WHERE { VALUES (?g ?x ?p) { (1 1 0.0) (1 3 0.0) (2 1 1.0) (2 3 1.0) (3 1 0.5) (3 3 0.5) } }"
				+ " GROUP BY ?g ORDER BY ?g");
		assertThat(column(rows, "pc")).containsExactly("1", "3", "2");
		assertThat(column(rows, "pd")).containsExactly("1", "3", "1");
		assertThat(lit(rows.get(0), "aq").doubleValue()).isEqualTo(1.0);
		assertThat(lit(rows.get(1), "aq").doubleValue()).isEqualTo(3.0);
		assertThat(lit(rows.get(2), "aq").doubleValue()).isBetween(1.0, 3.0);
	}

	@Test
	void unboundOrInvalidFractionLeavesAggregateUnbound() {
		List<BindingSet> rows = query("SELECT (agg:percentileCont(?x, ?p) AS ?pc) (agg:percentileDisc(?x, ?p) AS ?pd)"
				+ " (agg:approxQuantile(?x, ?p) AS ?aq) WHERE { VALUES (?x ?p) { (1 UNDEF) (2 UNDEF) } }");
		assertThat(rows.get(0).hasBinding("pc")).isFalse();
		assertThat(rows.get(0).hasBinding("pd")).isFalse();
		assertThat(rows.get(0).hasBinding("aq")).isFalse();
		rows = query("SELECT (agg:percentileCont(?x, 1.5) AS ?pc) (agg:percentileDisc(?x, -1) AS ?pd)"
				+ " (agg:approxQuantile(?x, \"0.5\") AS ?aq) (COUNT(?x) AS ?n) WHERE { VALUES ?x { 1 2 } }");
		assertThat(rows.get(0).hasBinding("pc")).isFalse();
		assertThat(rows.get(0).hasBinding("pd")).isFalse();
		assertThat(rows.get(0).hasBinding("aq")).isFalse();
		assertThat(str(rows.get(0), "n")).isEqualTo("2");
		// pins current behaviour: a row whose fraction is unbound is skipped, the rows with a fraction are aggregated
		rows = query("SELECT (agg:percentileDisc(?x, ?p) AS ?pd) WHERE { VALUES (?x ?p) { (1 UNDEF) (2 0.5) } }");
		assertThat(str(rows.get(0), "pd")).isEqualTo("2");
	}

	@Test
	void percentileBoundaryFractionsAndExactInterpolation() {
		List<BindingSet> rows = query("SELECT (agg:percentileCont(?x, 0) AS ?min) (agg:percentileCont(?x, 1) AS ?max)"
				+ " (agg:percentileCont(?x, 0.5) AS ?mid) (agg:percentileDisc(?x, 0.5) AS ?disc)"
				+ " (agg:approxQuantile(?x, 0) AS ?amin) (agg:approxQuantile(?x, 1) AS ?amax)"
				+ " WHERE { VALUES ?x { 4 1 3 2 } }");
		assertThat(str(rows.get(0), "min")).isEqualTo("1");
		assertThat(str(rows.get(0), "max")).isEqualTo("4");
		assertThat(str(rows.get(0), "mid")).isEqualTo("2.5");
		assertThat(str(rows.get(0), "disc")).isEqualTo("2");
		assertThat(lit(rows.get(0), "amin").doubleValue()).isEqualTo(1.0);
		assertThat(lit(rows.get(0), "amax").doubleValue()).isEqualTo(4.0);
	}

	// ------------------------------------------------------------------ arrayAgg round trips

	@Test
	void arrayAggRoundTripThroughUnnestReproducesTheMultiset() {
		List<BindingSet> rows = query("SELECT ?e WHERE { { SELECT (agg:arrayAgg(?x) AS ?arr) WHERE {"
				+ " VALUES ?x { 1 1 2 \"a\" \"a\"@en <urn:x> 1.5 \"NaN\"^^xsd:double \"7\"^^xsd:byte 01 1e0 } } }"
				+ " ?arr arrf:unnest ?e }");
		List<Value> expected = List.of(VF.createLiteral("1", XSD.INTEGER), VF.createLiteral("1", XSD.INTEGER),
				VF.createLiteral("2", XSD.INTEGER), VF.createLiteral("a"), VF.createLiteral("a", "en"),
				VF.createIRI("urn:x"), VF.createLiteral("1.5", XSD.DECIMAL), VF.createLiteral("NaN", XSD.DOUBLE),
				VF.createLiteral("7", XSD.BYTE), VF.createLiteral("01", XSD.INTEGER),
				VF.createLiteral("1e0", XSD.DOUBLE));
		List<Value> actual = new ArrayList<>();
		for (BindingSet row : rows) {
			actual.add(row.getValue("e"));
		}
		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		// derived numeric types and non-canonical lexical forms come back with their exact datatype and form
		assertThat(actual).anyMatch(v -> v instanceof Literal l && l.getDatatype().equals(XSD.BYTE));
		assertThat(actual).anyMatch(v -> v instanceof Literal l && l.getLabel().equals("01"));
		assertThat(actual).anyMatch(v -> v instanceof Literal l && l.getLabel().equals("1e0"));
	}

	@Test
	void arrayAggRoundTripPreservesBlankNodeIdentity() {
		List<BindingSet> rows = query("SELECT ?e ?tag WHERE { { SELECT (agg:arrayAgg(?b) AS ?arr) WHERE {"
				+ " ?b ex:kind ex:bnode } } ?arr arrf:unnest ?e . ?e ex:tag ?tag } ORDER BY ?tag");
		assertThat(rows).hasSize(2);
		assertThat(column(rows, "tag")).containsExactly("one", "two");
		for (BindingSet row : rows) {
			assertThat(row.getValue("e")).isInstanceOf(BNode.class);
		}
		List<BindingSet> encoded = query(
				"SELECT (agg:arrayAgg(?b) AS ?arr) WHERE { ?b ex:kind ex:bnode }");
		assertThat(str(encoded.get(0), "arr")).matches("\\[\\{\"@id\":\"_:[^\"]+\"\\},\\{\"@id\":\"_:[^\"]+\"\\}\\]");
	}

	@Test
	void arrayAggDistinctKeepsFirstSeenOrderAndSkipsUnbound() {
		List<BindingSet> rows = query("SELECT (agg:arrayAgg(?x) AS ?all) (agg:arrayAgg(DISTINCT ?x) AS ?distinct)"
				+ " WHERE { VALUES ?x { 3 UNDEF 1 3 2 1 } }");
		assertThat(str(rows.get(0), "all")).isEqualTo("[3,1,3,2,1]");
		assertThat(str(rows.get(0), "distinct")).isEqualTo("[3,1,2]");
	}

	// ------------------------------------------------------------------ approxCountDistinct / argMin

	@Test
	void approxCountDistinctAgreesWithCountDistinctOnTermEquality() {
		List<BindingSet> rows = query("SELECT (COUNT(DISTINCT ?x) AS ?exact) (agg:approxCountDistinct(?x) AS ?approx)"
				+ " WHERE { VALUES ?x { 1 1.0 \"1\"^^xsd:integer 1 \"1\" \"1\"@en 1e0 } }");
		assertThat(str(rows.get(0), "exact")).isEqualTo("5");
		assertThat(str(rows.get(0), "approx")).isEqualTo("5");
		assertThat(lit(rows.get(0), "approx").getCoreDatatype()).isEqualTo(CoreDatatype.XSD.INTEGER);
	}

	@Test
	void argMinArgMaxWithDistinctAndTies() {
		// pins current behaviour: DISTINCT is accepted on argMin/argMax and does not change the result; ties on the
		// key keep the value seen first
		List<BindingSet> rows = query("SELECT (agg:argMax(?e, ?salary) AS ?top) (agg:argMax(DISTINCT ?e, ?salary)"
				+ " AS ?topDistinct) (agg:argMin(DISTINCT ?salary, ?salary) AS ?min)"
				+ " WHERE { { SELECT ?e ?salary WHERE { ?e ex:dept ex:eng ; ex:salary ?salary } ORDER BY ?e } }");
		assertThat(str(rows.get(0), "top")).isEqualTo("http://example.org/e5");
		assertThat(str(rows.get(0), "topDistinct")).isEqualTo("http://example.org/e5");
		assertThat(str(rows.get(0), "min")).isEqualTo("50");
	}
}
